import org.jetbrains.annotations.Nullable;

import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

import static com.minecolonies.api.research.util.ResearchConstants.CITIZEN_CAP;
import static com.minecolonies.api.util.constant.Constants.*;
import static com.minecolonies.api.util.constant.NbtTagConstants.TAG_CITIZENS;
import static com.minecolonies.api.util.constant.NbtTagConstants.TAG_ID;
import static com.minecolonies.api.util.constant.TranslationConstants.*;

public class CitizenManager implements ICitizenManager
{
    /**
     * Map of citizens with ID,CitizenData
     */
    @NotNull
    private final Map<Integer, ICitizenData> citizens = new HashMap<>();

    /**
     * Variables to determine if citizens have to be updated on the client side.
     */
    private boolean isCitizensDirty = false;

    /**
     * The highest citizen id.
     */
    private int topCitizenId = 0;

    /**
     * Max citizens without housing.
     */
    private int maxCitizens = 0;

    /**
     * Max citizens considering the spot in the empty guard tower.
     */
    private int potentialMaxCitizens;

    /**
     * The colony of the manager.
     */
    private final Colony colony;

    /**
     * The initial citizen spawn interval
     */
    private int respawnInterval = 30 * TICKS_SECOND;

    /**
     * The citizen spawn interval
     */
    private int citizenRespawnTimer = 5 * 60 * TICKS_SECOND;

    /**
     * Random obj.
     */
    private Random random = new Random();

    /**
     * Whether all citizens excluding guards are sleeping
     */
    private boolean areCitizensSleeping;

    /**
     * Creates the Citizenmanager for a colony.
     *
     * @param colony the colony.
     */
    public CitizenManager(final Colony colony)
    {
        this.colony = colony;
    }

    @Override
    public void registerCivilian(final AbstractCivilianEntity entity)
    {
        if (entity.getCivilianID() == 0 || citizens.get(entity.getCivilianID()) == null)
        {
            if (!entity.isAddedToWorld())
            {
                Log.getLogger().warn("Discarding entity not added to world, should be only called after:", new Exception());
            }
            entity.remove(Entity.RemovalReason.DISCARDED);
            return;
        }

        final ICitizenData data = citizens.get(entity.getCivilianID());

        if (data == null || !entity.getUUID().equals(data.getUUID()))
        {
            if (!entity.isAddedToWorld())
            {
                Log.getLogger().warn("Discarding entity not added to world, should be only called after:", new Exception());
            }
            entity.remove(Entity.RemovalReason.DISCARDED);
            return;
        }

        final Optional<AbstractEntityCitizen> existingCitizen = data.getEntity();

        if (existingCitizen.isEmpty())
        {
            data.setEntity(entity);
            return;
        }

        if (!entity.isAddedToWorld())
        {
            Log.getLogger().warn("Discarding entity not added to world, should be only called after:", new Exception());
        }
        entity.remove(Entity.RemovalReason.DISCARDED);
    }

    @Override
    public void unregisterCivilian(final AbstractCivilianEntity entity)
    {
        final ICitizenData data = citizens.get(entity.getCivilianID());
        if (data != null && data.getEntity().isPresent() && data.getEntity().get() == entity)
        {
            citizens.get(entity.getCivilianID()).setEntity(null);
        }
    }

    @Override
    public void read(@NotNull final CompoundTag compound)
    {
        citizens.forEach((id, citizen) -> citizen.getEntity().ifPresent(e -> e.remove(Entity.RemovalReason.DISCARDED)));
        citizens.clear();
        //  Citizens before Buildings, because Buildings track the Citizens
        citizens.putAll(NBTUtils.streamCompound(compound.getList(TAG_CITIZENS, Tag.TAG_COMPOUND))
                          .map(this::deserializeCitizen)
                          .collect(Collectors.toMap(ICitizenData::getId, Function.identity())));

        // Update child state after loading citizen data
        colony.updateHasChilds();
    }

    /**
     * Creates a citizen data from NBT
     *
     * @param compound NBT
     * @return citizen data
     */
    private ICitizenData deserializeCitizen(@NotNull final CompoundTag compound)
    {
        final ICitizenData data = ICitizenDataManager.getInstance().createFromNBT(compound, colony);
        topCitizenId = Math.max(topCitizenId, data.getId());
        return data;
    }

    @Override
    public void write(@NotNull final CompoundTag compoundNBT)
    {
        @NotNull final ListTag citizenTagList = citizens.values().stream().map(citizen -> citizen.serializeNBT()).collect(NBTUtils.toListNBT());
        compoundNBT.put(TAG_CITIZENS, citizenTagList);
    }

    @Override
    public void sendPackets(
      @NotNull final Set<ServerPlayer> closeSubscribers,
      @NotNull final Set<ServerPlayer> newSubscribers)
    {
        if (isCitizensDirty || !newSubscribers.isEmpty())
        {
            final Set<ServerPlayer> players = new HashSet<>();
            if (isCitizensDirty)
            {
                players.addAll(closeSubscribers);
            }
            players.addAll(newSubscribers);
            for (@NotNull final ICitizenData citizen : citizens.values())
            {
                if (citizen.isDirty() || !newSubscribers.isEmpty())
                {
                    final ColonyViewCitizenViewMessage message = new ColonyViewCitizenViewMessage(colony, citizen);
                    players.forEach(player -> Network.getNetwork().sendToPlayer(message, player));
                }
            }
        }
    }

    @Override
    public <T extends ICivilianData> T spawnOrCreateCivilian(final T data, final Level world, List<BlockPos> spawnPositions, final boolean force)
    {
        if (!colony.getSettings().getSetting(BuildingTownHall.MOVE_IN).getValue() && !force)
        {
            return data;
        }

        if (colony.getServerBuildingManager().hasTownHall() && spawnPositions.isEmpty())
        {
            spawnPositions = new ArrayList<>();
            spawnPositions.add(colony.getServerBuildingManager().getTownHall().getPosition());
        }

        for (final BlockPos spawnLocation : spawnPositions)
        {
            if (spawnLocation == null || spawnLocation.equals(BlockPos.ZERO))
            {
                continue;
            }

            if (WorldUtil.isEntityBlockLoaded(world, spawnLocation))
            {
                BlockPos calculatedSpawn = EntityUtils.getSpawnPoint(world, spawnLocation);
                if (calculatedSpawn != null)
                {
                    return (T) spawnCitizenOnPosition((ICitizenData) data, world, force, calculatedSpawn);
                }
                else if (colony.getServerBuildingManager().hasTownHall() && spawnLocation.equals(colony.getServerBuildingManager().getTownHall().getPosition()))
                {
                    final BlockPos townhallPos = colony.getServerBuildingManager().getTownHall().getPosition();
                    MessageUtils.format(WARNING_COLONY_NO_ARRIVAL_SPACE, townhallPos.getX(), townhallPos.getY(), townhallPos.getZ()).sendTo(colony).forAllPlayers();
                }
            }
        }

        return data;
    }

    @NotNull
    private ICitizenData spawnCitizenOnPosition(
      @Nullable final ICitizenData data,
      @NotNull final Level world,
      final boolean force,
      final BlockPos spawnPoint)
    {
        ICitizenData citizenData = data;
        if (citizenData == null)
        {
            citizenData = createAndRegisterCivilianData();

            if (getMaxCitizens() >= getCurrentCitizenCount() && !force)
            {
                if (maxCitizensFromResearch() <= getCurrentCitizenCount())
                {
                    MessageUtils.format(WARNING_MAX_CITIZENS_RESEARCH, colony.getName()).sendTo(colony).forAllPlayers();
                }
                else
                {
                    MessageUtils.format(WARNING_MAX_CITIZENS_CONFIG, colony.getName()).sendTo(colony).forAllPlayers();
                }
            }

            colony.getEventDescriptionManager().addEventDescription(new CitizenSpawnedEvent(spawnPoint, citizenData.getName()));
        }

        if (world instanceof ServerLevel serverLevel)
        {
            Entity existing = serverLevel.getEntity(citizenData.getUUID());
            if (existing != null)
            {
                existing.discard();
                existing = serverLevel.getEntity(citizenData.getUUID());
                if (existing != null)
                {
                    serverLevel.entityManager.stopTracking(existing);
                }
            }
        }

        final EntityCitizen entity = (EntityCitizen) ModEntities.CITIZEN.create(world);

        entity.setUUID(citizenData.getUUID());
        entity.setPos(spawnPoint.getX() + HALF_BLOCK, spawnPoint.getY() + SLIGHTLY_UP, spawnPoint.getZ() + HALF_BLOCK);

        entity.setCitizenId(citizenData.getId());
        entity.getCitizenColonyHandler().setColonyId(colony.getID());

        world.addFreshEntity(entity);
        if (entity.isAddedToWorld())
        {
            entity.getCitizenColonyHandler().registerWithColony(citizenData.getColony().getID(), citizenData.getId());
        }

        markDirty();
        return citizenData;
    }

    @Override
    public ICitizenData createAndRegisterCivilianData()
    {
        //This ensures that citizen IDs are getting reused.
        //That's needed to prevent bugs when calling IDs that are not used.
        for (int i = 1; i <= this.getCurrentCitizenCount() + 1; i++)
        {
            if (this.getCivilian(i) == null)
            {
                topCitizenId = i;
                break;
            }
        }

        final CitizenData citizenData = new CitizenData(topCitizenId, colony);
        citizenData.initForNewCivilian();
        citizens.put(citizenData.getId(), citizenData);

        return citizenData;
    }

    @Override
    public ICitizenData resurrectCivilianData(@NotNull final CompoundTag compoundNBT, final boolean resetId, @NotNull final Level world, final BlockPos spawnPos)
    {
        //This ensures that citizen IDs are getting reused.
        //That's needed to prevent bugs when calling IDs that are not used.
        for (int i = 1; i <= this.getCurrentCitizenCount() + 1; i++)
        {
            if (this.getCivilian(i) == null)
            {
                topCitizenId = i;
                break;
            }
        }

        if(resetId)
        {
            compoundNBT.putInt(TAG_ID, topCitizenId);
        }

        final ICitizenData citizenData = deserializeCitizen(compoundNBT);
        citizenData.onResurrect();
        citizens.put(citizenData.getId(), citizenData);
        spawnOrCreateCitizen(citizenData, world, spawnPos);

        IMinecoloniesAPI.getInstance().getEventBus().post(new CitizenAddedModEvent(citizenData, CitizenAddedModEvent.CitizenAddedSource.RESURRECTED));
        return citizenData;
    }

    @Override
    public void removeCivilian(@NotNull final ICivilianData citizen)
    {
        if (!(citizen instanceof ICitizenData))
        {
            return;
        }

        //Remove the Citizen
        citizens.remove(citizen.getId());

        for (@NotNull final IBuilding building : colony.getServerBuildingManager().getBuildings().values())
        {
            for (final AbstractAssignedCitizenModule assignedCitizenModule : building.getModulesByType(AbstractAssignedCitizenModule.class))
            {
                assignedCitizenModule.removeCitizen((ICitizenData) citizen);
            }
        }

        colony.getWorkManager().clearWorkForCitizen((ICitizenData) citizen);

        //  Inform Subscribers of removed citizen
        for (final ServerPlayer player : colony.getPackageManager().getCloseSubscribers())
        {
            Network.getNetwork().sendToPlayer(new ColonyViewRemoveCitizenMessage(colony, citizen.getId()), player);
        }

        calculateMaxCitizens();
        markDirty();
        colony.markDirty();
    }

    @Override
    public ICitizenData getJoblessCitizen()
    {
        for (@NotNull final ICitizenData citizen : citizens.values())
        {
            if (citizen.getWorkBuilding() == null && !citizen.isChild())
            {
                return citizen;
            }
        }

        return null;
    }

    @Override
    public void calculateMaxCitizens()
    {
        int newMaxCitizens = 0;
        int potentialMax = 0;

        for (final IBuilding b : colony.getServerBuildingManager().getBuildings().values())
        {
            if (b.getBuildingLevel() > 0)
            {
                if (b.hasModule(BuildingModules.BED) && b.hasModule(WorkAtHomeBuildingModule.class))
                {
                    final WorkAtHomeBuildingModule module = b.getFirstModuleOccurance(WorkAtHomeBuildingModule.class);
                    newMaxCitizens += b.getAllAssignedCitizen().size();
                    potentialMax += module.getModuleMax() - b.getAllAssignedCitizen().size();
                }
                else if (b.hasModule(LivingBuildingModule.class))
                {
                    final LivingBuildingModule module = b.getFirstModuleOccurance(LivingBuildingModule.class);
                    if (HiringMode.LOCKED.equals(module.getHiringMode()))
                    {
                        newMaxCitizens += module.getAssignedCitizen().size();
                    }
                    else
                    {
                        newMaxCitizens += module.getModuleMax();
                    }
                }
            }
        }
        if (getMaxCitizens() != newMaxCitizens || getPotentialMaxCitizens() != potentialMax + newMaxCitizens)
        {
            setMaxCitizens(newMaxCitizens);
            setPotentialMaxCitizens(potentialMax + newMaxCitizens);
            colony.markDirty();
        }
    }

    /**
     * Spawn a brand new Citizen.
     */
    public void spawnOrCreateCitizen()
    {
        spawnOrCreateCitizen(null, colony.getWorld(), null);
    }

    @NotNull
    @Override
    public Map<Integer, ICivilianData> getCivilianDataMap()
    {
        return Collections.unmodifiableMap(citizens);
    }

    @Override
    public void markDirty()
    {
        colony.markDirty();
        isCitizensDirty = true;
    }

    @Override
    public ICitizenData getCivilian(final int citizenId)
    {
        return citizens.get(citizenId);
    }

    @Override
    public void clearDirty()
    {
        isCitizensDirty = false;
        citizens.values().forEach(ICitizenData::clearDirty);
    }

    @Override
    public List<ICitizenData> getCitizens()
    {
        return new ArrayList<>(citizens.values());
    }

    @Override
    public int getMaxCitizens()
    {
        return (int) Math.max(1, Math.min(maxCitizens, Math.min(maxCitizensFromResearch(), MineColonies.getConfig().getServer().maxCitizenPerColony.get())));
    }

    @Override
    public int getPotentialMaxCitizens()
    {
        return (int) Math.max(1, Math.min(potentialMaxCitizens, Math.min(maxCitizensFromResearch(), MineColonies.getConfig().getServer().maxCitizenPerColony.get())));
    }

    @Override
    public double maxCitizensFromResearch()
    {
        if (MinecoloniesAPIProxy.getInstance().getGlobalResearchTree().hasResearchEffect(CITIZEN_CAP))
        {
            final int max = Math.max(CitizenConstants.CITIZEN_LIMIT_DEFAULT, (int) colony.getResearchManager().getResearchEffects().getEffectStrength(CITIZEN_CAP));
            return Math.min(max, MineColonies.getConfig().getServer().maxCitizenPerColony.get());
        }
        else
        {
            return MineColonies.getConfig().getServer().maxCitizenPerColony.get();
        }
    }

    /**
     * Get the current amount of citizens, might be bigger then {@link #getMaxCitizens()}
     *
     * @return The current amount of citizens in the colony.
     */
    @Override
    public int getCurrentCitizenCount()
    {
        return citizens.size();
    }

    @Override
    public void setMaxCitizens(final int newMaxCitizens)
    {
        this.maxCitizens = newMaxCitizens;
    }

    @Override
    public void setPotentialMaxCitizens(final int newPotentialMax)
    {
        this.potentialMaxCitizens = newPotentialMax;
    }

    @Override
    public void injectModifier(final IHappinessModifier modifier)
    {
        for (final ICitizenData citizenData : citizens.values())
        {
            citizenData.getCitizenHappinessHandler().addModifier(modifier);
        }
    }

    @Override
    public void checkCitizensForHappiness()
    {
        for (final ICitizenData citizenData : citizens.values())
        {
            citizenData.getCitizenHappinessHandler().processDailyHappiness(citizenData);
        }
    }

    @Override
    public boolean tickCitizenData(final int tickRate)
    {
        for (ICitizenData iCitizenData : this.getCitizens())
        {
            iCitizenData.update(tickRate);
        }
        return false;
    }

    /**
     * Updates the citizen entities when needed and spawn the initial citizens on colony tick.
     *
     * @param colony the colony being ticked.
     */
    @Override
    public void onColonyTick(final IColony colony)
    {
        if (colony.getServerBuildingManager().hasTownHall() && (citizenRespawnTimer -= 500) < 0)
        {
            citizenRespawnTimer = 5 * 60 * TICKS_SECOND;
            getCitizens().stream().filter(Objects::nonNull).forEach(ICitizenData::updateEntityIfNecessary);
        }

        //  Spawn initial Citizens
        if (colony.getSettings().getSetting(BuildingTownHall.MOVE_IN).getValue() && colony.getServerBuildingManager().hasTownHall() && getCitizens().size() < MineColonies.getConfig().getServer().initialCitizenAmount.get())
        {
            respawnInterval -= 500 + (SECONDS_A_MINUTE * colony.getServerBuildingManager().getTownHall().getBuildingLevel());

            if (respawnInterval <= 0)
            {
                respawnInterval = 60 * TICKS_SECOND;
                int femaleCount = 0;
                for (ICitizenData citizens : getCitizens())
                {
                    femaleCount += citizens.isFemale() ? 1 : 0;
                }

                final boolean firstCitizen = getCitizens().size() == 0;
                final ICitizenData newCitizen = createAndRegisterCivilianData();
                if (firstCitizen)
                {
                    colony.getQuestManager().injectAvailableQuest(new QuestInstance(new ResourceLocation(MOD_ID, "tutorial/welcome"), colony, List.of(new CitizenTriggerReturnData(newCitizen))));
                }

                // For first citizen, give a random chance of male or female.
                if (getCitizens().size() == 1)
                {
                    newCitizen.setGenderAndGenerateName(random.nextBoolean());
                }
                // Otherwise, set the new colonist's gender to whatever gender is less common.
                // Use double division to avoid getting two male colonists in a row for the first set.
                else if (femaleCount < (getCitizens().size() - 1) / 2.0)
                {
                    newCitizen.setGenderAndGenerateName(true);
                }
                else
                {
                    newCitizen.setGenderAndGenerateName(false);
                }

                spawnOrCreateCivilian(newCitizen, colony.getWorld(), List.of(colony.getServerBuildingManager().getTownHall().getPosition()), true);

                IMinecoloniesAPI.getInstance().getEventBus().post(new CitizenAddedModEvent(newCitizen, CitizenAddedModEvent.CitizenAddedSource.INITIAL));
                colony.getEventDescriptionManager().addEventDescription(new CitizenSpawnedEvent(colony.getServerBuildingManager().getTownHall().getPosition(),
                      newCitizen.getName()));
            }
        }
    }

    @Override
    public void updateCitizenMourn(final ICitizenData data, final boolean mourn)
    {
        for (final ICitizenData citizen : getCitizens())
        {
            if (mourn)
            {
                if (!(citizen.getJob() instanceof AbstractJobGuard) && !(citizen.getJob() instanceof JobUndertaker) && (citizen.isRelatedTo(data) || citizen.doesLiveWith(data)))
                {
                    citizen.getCitizenMournHandler().addDeceasedCitizen(data.getName());
                }
            }
            else
            {
                citizen.getCitizenMournHandler().removeDeceasedCitizen(data.getName());
            }
            citizen.onDeath(data.getId());
        }
    }

    @Override
    public ICitizenData getRandomCitizen()
    {
        return (ICitizenData) citizens.values().toArray()[random.nextInt(citizens.values().size())];
    }

    @Override
    public void updateCitizenSleep(final boolean sleep)
    {
        this.areCitizensSleeping = sleep;
    }

    @Override
    public void onCitizenSleep()
    {
        for (final ICitizenData citizenData : citizens.values())
        {
            if (!(citizenData.isAsleep() || citizenData.getJob() instanceof AbstractJobGuard))
            {
                return;
            }
        }

        if (!this.areCitizensSleeping)
        {
            MessageUtils.format(ALL_CITIZENS_ARE_SLEEPING).sendTo(colony).forAllPlayers();
        }

        this.areCitizensSleeping = true;
    }

    @Override
    public void onWakeUp()
    {
        for (final ICitizenData citizenData : citizens.values())
        {
            citizenData.updateEntityIfNecessary();
            if (citizenData.getCitizenMournHandler().isMourning())
            {
                citizenData.getCitizenMournHandler().clearDeceasedCitizen();
                citizenData.getCitizenMournHandler().setMourning(false);
            }
            else
            {
                if (citizenData.getCitizenMournHandler().shouldMourn())
                {
                    citizenData.getCitizenMournHandler().setMourning(true);
                }
            }
        }
    }

    @Override
    public void afterBuildingLoad()
    {
        calculateMaxCitizens();

        for(final ICitizenData data: citizens.values())
        {
            data.onBuildingLoad();
        }
    }

    @Override
    public void onFlagChange()
    {
        for (ICitizenData citizen : this.getCitizens())
        {
            if (citizen.getEntity().isPresent() && citizen.getJob() instanceof IJobWithColonyFlag flagUser)
            {
                flagUser.onColonyFlagChanged();
            }
        }
    }
}

package com.minecolonies.core.colony.managers;

import com.minecolonies.api.colony.ICitizenData;
import com.minecolonies.api.colony.ICivilianData;
import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.colony.IVisitorData;
import com.minecolonies.api.colony.managers.interfaces.IVisitorManager;
import com.minecolonies.api.entity.ModEntities;
import com.minecolonies.api.entity.citizen.AbstractCivilianEntity;
import com.minecolonies.api.entity.citizen.AbstractEntityCitizen;
import com.minecolonies.api.util.EntityUtils;
import com.minecolonies.api.util.Log;
import com.minecolonies.api.util.MessageUtils;
import com.minecolonies.api.util.WorldUtil;
import com.minecolonies.core.Network;
import com.minecolonies.core.colony.VisitorData;
import com.minecolonies.core.colony.buildings.workerbuildings.BuildingTownHall;
import com.minecolonies.core.entity.visitor.VisitorCitizen;
import com.minecolonies.core.network.messages.client.colony.ColonyVisitorViewDataMessage;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.level.Level;
import org.jetbrains.annotations.NotNull;

import java.util.*;

import static com.minecolonies.api.util.constant.Constants.SLIGHTLY_UP;
import static com.minecolonies.api.util.constant.PathingConstants.HALF_A_BLOCK;
import static com.minecolonies.api.util.constant.TranslationConstants.WARNING_COLONY_NO_ARRIVAL_SPACE;

/**
 * Manages all visiting entities to the colony
 */
public class VisitorManager implements IVisitorManager
{
    /**
     * NBT Tags
     */
    public static String TAG_VISIT_MANAGER = "visitManager";
    public static String TAG_VISITORS      = "visitors";
    public static String TAG_NEXTID        = "nextID";

    /**
     * Map with visitor ID and data
     */
    private Map<Integer, IVisitorData> visitorMap = new HashMap<>();

    /**
     * Whether this manager is dirty and needs re-serialize
     */
    private boolean isDirty = false;

    /**
     * The colony of the manager.
     */
    private final IColony colony;

    /**
     * The next free ID
     */
    private int nextVisitorID = -1;

    public VisitorManager(final IColony colony)
    {
        this.colony = colony;
    }

    @Override
    public void registerCivilian(final AbstractCivilianEntity visitor)
    {
        if (visitor.getCivilianID() == 0 || visitorMap.get(visitor.getCivilianID()) == null)
        {
            if (!visitor.isAddedToWorld())
            {
                Log.getLogger().warn("Discarding entity not added to world, should be only called after:", new Exception());
            }
            visitor.remove(Entity.RemovalReason.DISCARDED);
            return;
        }

        final ICitizenData data = visitorMap.get(visitor.getCivilianID());

        if (data == null || !visitor.getUUID().equals(data.getUUID()))
        {
            if (!visitor.isAddedToWorld())
            {
                Log.getLogger().warn("Discarding entity not added to world, should be only called after:", new Exception());
            }
            visitor.remove(Entity.RemovalReason.DISCARDED);
            return;
        }

        final Optional<AbstractEntityCitizen> existingCitizen = data.getEntity();

        if (!existingCitizen.isPresent())
        {
            data.setEntity(visitor);
            visitor.setCivilianData(data);
            return;
        }

        if (existingCitizen.get() == visitor)
        {
            return;
        }

        if (visitor.isAlive())
        {
            existingCitizen.get().remove(Entity.RemovalReason.DISCARDED);
            data.setEntity(visitor);
            visitor.setCivilianData(data);
            return;
        }

        if (!visitor.isAddedToWorld())
        {
            Log.getLogger().warn("Discarding entity not added to world, should be only called after:", new Exception());
        }
        visitor.remove(Entity.RemovalReason.DISCARDED);
    }

    @Override
    public void unregisterCivilian(final AbstractCivilianEntity entity)
    {
        final ICitizenData data = visitorMap.get(entity.getCivilianID());
        if (data != null && data.getEntity().isPresent() && data.getEntity().get() == entity)
        {
            visitorMap.get(entity.getCivilianID()).setEntity(null);
        }
    }

    @Override
    public void read(@NotNull final CompoundTag compound)
    {
        if (compound.contains(TAG_VISIT_MANAGER))
        {
            final CompoundTag visitorManagerNBT = compound.getCompound(TAG_VISIT_MANAGER);
            final ListTag citizenList = visitorManagerNBT.getList(TAG_VISITORS, Tag.TAG_COMPOUND);
            for (final Tag citizen : citizenList)
            {
                final IVisitorData data = VisitorData.loadVisitorFromNBT(colony, (CompoundTag) citizen);
                visitorMap.put(data.getId(), data);
            }

            nextVisitorID = visitorManagerNBT.getInt(TAG_NEXTID);
        }
        markDirty();
    }

    @Override
    public void write(@NotNull final CompoundTag compoundNBT)
    {
        final CompoundTag visitorManagerNBT = new CompoundTag();

        final ListTag citizenList = new ListTag();
        for (Map.Entry<Integer, IVisitorData> entry : visitorMap.entrySet())
        {
            citizenList.add(entry.getValue().serializeNBT());
        }

        visitorManagerNBT.put(TAG_VISITORS, citizenList);
        visitorManagerNBT.putInt(TAG_NEXTID, nextVisitorID);
        compoundNBT.put(TAG_VISIT_MANAGER, visitorManagerNBT);
    }

    @Override
    public void sendPackets(@NotNull final Set<ServerPlayer> closeSubscribers, @NotNull final Set<ServerPlayer> newSubscribers)
    {
        Set<IVisitorData> toSend = null;
        boolean refresh = !newSubscribers.isEmpty() || this.isDirty;

        if (refresh)
        {
            toSend = new HashSet<>(visitorMap.values());
            for (final IVisitorData data : visitorMap.values())
            {
                data.clearDirty();
            }
            this.clearDirty();
        }
        else
        {
            for (final IVisitorData data : visitorMap.values())
            {
                if (data.isDirty())
                {
                    if (toSend == null)
                    {
                        toSend = new HashSet<>();
                    }

                    toSend.add(data);
                }
                data.clearDirty();
            }
        }

        if (toSend == null || toSend.isEmpty())
        {
            return;
        }

        Set<ServerPlayer> players = new HashSet<>(newSubscribers);
        players.addAll(closeSubscribers);

        final ColonyVisitorViewDataMessage message = new ColonyVisitorViewDataMessage(colony, toSend, refresh);

        for (final ServerPlayer player : players)
        {
            Network.getNetwork().sendToPlayer(message, player);
        }
    }

    @NotNull
    @Override
    public Map<Integer, ICivilianData> getCivilianDataMap()
    {
        return Collections.unmodifiableMap(visitorMap);
    }

    @Override
    public IVisitorData getCivilian(final int citizenId)
    {
        return visitorMap.get(citizenId);
    }

    @Override
    public <T extends IVisitorData> T getVisitor(int citizenId)
    {
        return (T) visitorMap.get(citizenId);
    }

    @Override
    public <T extends ICivilianData> T spawnOrCreateCivilian(T data, final Level world, List<BlockPos> spawnPositions, final boolean force)
    {
        if (!colony.getServerBuildingManager().hasTownHall() || (!colony.getSettings().getSetting(BuildingTownHall.MOVE_IN).getValue() && !force))
        {
            return data;
        }

        if (colony.getServerBuildingManager().hasTownHall())
        {
            spawnPositions = new ArrayList<>(spawnPositions);
            spawnPositions.add(colony.getServerBuildingManager().getTownHall().getPosition());
        }

        for (final BlockPos spawnLocation : spawnPositions)
        {
            if (spawnLocation == null || spawnLocation.equals(BlockPos.ZERO))
            {
                continue;
            }

            if (WorldUtil.isEntityBlockLoaded(world, spawnLocation))
            {
                BlockPos calculatedSpawn = EntityUtils.getSpawnPoint(world, spawnLocation);
                if (calculatedSpawn != null)
                {
                    VisitorCitizen citizenEntity = (VisitorCitizen) ModEntities.VISITOR.create(colony.getWorld());

                    if (citizenEntity == null)
                    {
                        return data;
                    }

                    citizenEntity.setUUID(data.getUUID());
                    citizenEntity.setPos(calculatedSpawn.getX() + HALF_A_BLOCK, calculatedSpawn.getY() + SLIGHTLY_UP, calculatedSpawn.getZ() + HALF_A_BLOCK);
                    world.addFreshEntity(citizenEntity);

                    citizenEntity.setCitizenId(data.getId());
                    citizenEntity.getCitizenColonyHandler().setColonyId(colony.getID());
                    if (citizenEntity.isAddedToWorld())
                    {
                        citizenEntity.getCitizenColonyHandler().registerWithColony(data.getColony().getID(), data.getId());
                    }

                    return data;
                }
            }
        }

        if (colony.getServerBuildingManager().hasTownHall() && WorldUtil.isEntityBlockLoaded(world, colony.getServerBuildingManager().getTownHall().getPosition()))
        {
            final BlockPos townhallPos = colony.getServerBuildingManager().getTownHall().getPosition();
            MessageUtils.format(WARNING_COLONY_NO_ARRIVAL_SPACE, townhallPos.getX(), townhallPos.getY(), townhallPos.getZ()).sendTo(colony).forAllPlayers();
        }
        return data;
    }

    @Override
    public IVisitorData createAndRegisterCivilianData()
    {
        markDirty();
        final IVisitorData data = new VisitorData(nextVisitorID--, colony);
        data.initForNewCivilian();
        visitorMap.put(data.getId(), data);
        return data;
    }

    @Override
    public void removeCivilian(@NotNull final ICivilianData citizen)
    {
        final IVisitorData data = visitorMap.remove(citizen.getId());
        if (data != null && data.getEntity().isPresent())
        {
            data.getEntity().get().remove(Entity.RemovalReason.DISCARDED);
        }
    }

    @Override
    public void markDirty()
    {
        this.isDirty = true;
    }

    @Override
    public void clearDirty()
    {
        this.isDirty = false;
    }

    @Override
    public void onColonyTick(final IColony colony)
    {
        if (colony.getServerBuildingManager().hasTownHall())
        {
            for (final IVisitorData data : visitorMap.values())
            {
                data.updateEntityIfNecessary();
            }
        }
    }
}

package com.minecolonies.core.datalistener;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.minecolonies.api.colony.requestsystem.StandardFactoryController;
import com.minecolonies.api.crafting.ItemStorage;
import com.minecolonies.core.Network;
import com.minecolonies.core.datalistener.model.Disease;
import com.minecolonies.core.network.messages.client.colony.GlobalDiseaseSyncMessage;
import io.netty.buffer.Unpooled;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.server.packs.resources.ResourceManager;
import net.minecraft.server.packs.resources.SimpleJsonResourceReloadListener;
import net.minecraft.util.GsonHelper;
import net.minecraft.util.RandomSource;
import net.minecraft.util.profiling.ProfilerFiller;
import net.minecraft.util.random.WeightedRandomList;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Loads and listens to diseases data.
 */
public class DiseasesListener extends SimpleJsonResourceReloadListener
{
    /**
     * Gson instance
     */
    private static final Gson GSON = new GsonBuilder().setPrettyPrinting().disableHtmlEscaping().create();

    /**
     * Json constants
     */
    private static final String KEY_NAME   = "name";
    private static final String KEY_RARITY = "rarity";
    private static final String KEY_ITEMS  = "items";

    /**
     * The map of diseases.
     */
    private static WeightedRandomList<Disease> DISEASES = WeightedRandomList.create();

    /**
     * Default constructor.
     */
    public DiseasesListener()
    {
        super(GSON, "colony/diseases");
    }

    /**
     * Sync to client.
     *
     * @param player to send it to.
     */
    public static void sendGlobalDiseasesPackets(final ServerPlayer player)
    {
        final FriendlyByteBuf byteBuf = new FriendlyByteBuf(Unpooled.buffer());
        byteBuf.writeInt(DISEASES.unwrap().size());
        for (final Disease disease : DISEASES.unwrap())
        {
            byteBuf.writeResourceLocation(disease.id());
            byteBuf.writeComponent(disease.name());
            byteBuf.writeInt(disease.rarity());
            byteBuf.writeInt(disease.cureItems().size());
            for (final ItemStorage cureItem : disease.cureItems())
            {
                StandardFactoryController.getInstance().serialize(byteBuf, cureItem);
            }
        }
        Network.getNetwork().sendToPlayer(new GlobalDiseaseSyncMessage(byteBuf), player);
    }

    /**
     * Read the data from the packet and parse it.
     *
     * @param byteBuf pck.
     */
    public static void readGlobalDiseasesPackets(final FriendlyByteBuf byteBuf)
    {
        final List<Disease> newDiseases = new ArrayList<>();
        final int size = byteBuf.readInt();
        for (int i = 0; i < size; i++)
        {
            final ResourceLocation id = byteBuf.readResourceLocation();
            final Component name = byteBuf.readComponent();
            final int rarity = byteBuf.readInt();

            final List<ItemStorage> cureItems = new ArrayList<>();
            final int itemCount = byteBuf.readInt();
            for (int j = 0; j < itemCount; j++)
            {
                cureItems.add(StandardFactoryController.getInstance().deserialize(byteBuf));
            }

            newDiseases.add(new Disease(id, name, rarity, cureItems));
        }
        DISEASES = WeightedRandomList.create(newDiseases);
    }

    /**
     * Get a collection of all possible diseases.
     *
     * @return the collection of diseases.
     */
    @NotNull
    public static List<Disease> getDiseases()
    {
        return DISEASES.unwrap();
    }

    /**
     * Get a specific disease by id.
     *
     * @param id the disease id.
     * @return the disease instance or null if it does not exist.
     */
    @Nullable
    public static Disease getDisease(final ResourceLocation id)
    {
        for (final Disease disease : DISEASES.unwrap())
        {
            if (disease.id().equals(id))
            {
                return disease;
            }
        }
        return null;
    }

    /**
     * Get a random disease from the list of diseases.
     *
     * @param random the input random source.
     * @return the random disease instance or null if no diseases exist.
     */
    @Nullable
    public static Disease getRandomDisease(final RandomSource random)
    {
        return DISEASES.getRandom(random).orElse(null);
    }

    @Override
    protected void apply(
      final @NotNull Map<ResourceLocation, JsonElement> jsonElementMap,
      final @NotNull ResourceManager resourceManager,
      final @NotNull ProfilerFiller profiler)
    {
        final List<Disease> diseases = new ArrayList<>();
        for (final Map.Entry<ResourceLocation, JsonElement> entry : jsonElementMap.entrySet())
        {
            if (!entry.getValue().isJsonObject())
            {
                return;
            }

            final JsonObject object = entry.getValue().getAsJsonObject();
            final Component name = Component.translatable(GsonHelper.getAsString(object, KEY_NAME));
            final int rarity = GsonHelper.getAsInt(object, KEY_RARITY);
            final List<ItemStorage> cureItems = new ArrayList<>();
            for (final JsonElement jsonElement : object.getAsJsonArray(KEY_ITEMS))
            {
                if (!jsonElement.isJsonObject())
                {
                    continue;
                }

                final ItemStorage cureItem = new ItemStorage(jsonElement.getAsJsonObject());
                // TODO: Apparently the healing doesn't fully work yet with multi-count cure items
                // for the sake of compatibility for now, revert the count to 1 despite what's in the JSON.
                cureItem.setAmount(1);
                cureItems.add(cureItem);
            }

            diseases.add(new Disease(entry.getKey(), name, rarity, cureItems));
        }
        DISEASES = WeightedRandomList.create(diseases);
    }
}

package com.minecolonies.core.entity.ai.minimal;

import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.colony.buildings.IBuilding;
import com.minecolonies.api.entity.ai.IStateAI;
import com.minecolonies.api.entity.ai.statemachine.states.CitizenAIState;
import com.minecolonies.api.entity.ai.statemachine.states.IState;
import com.minecolonies.api.entity.ai.statemachine.tickratestatemachine.TickingTransition;
import com.minecolonies.api.util.BlockPosUtil;
import com.minecolonies.api.util.MathUtils;
import com.minecolonies.api.util.Tuple;
import com.minecolonies.api.util.WorldUtil;
import com.minecolonies.core.colony.buildings.modules.GraveyardManagementModule;
import com.minecolonies.core.colony.buildings.workerbuildings.BuildingGraveyard;
import com.minecolonies.core.entity.citizen.EntityCitizen;
import com.minecolonies.core.entity.pathfinding.navigation.EntityNavigationUtils;
import com.minecolonies.core.tileentities.TileEntityNamedGrave;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.ai.targeting.TargetingConditions;
import net.minecraft.world.level.block.entity.BlockEntity;
import org.apache.commons.lang3.StringUtils;

import java.util.Iterator;
import java.util.List;
import java.util.Set;

import static com.minecolonies.api.util.constant.Constants.DEFAULT_SPEED;

/**
 * Citizen mourning goal. Has citizens randomly walk around townhall.
 */
public class EntityAIMournCitizen implements IStateAI
{
    /**
     * Different mourning states.
     */
    public enum MourningState implements IState
    {
        DECIDE,
        WALKING_TO_TOWNHALL,
        WANDERING,
        STARING,
        WALKING_TO_GRAVEYARD,
        WANDER_AT_GRAVEYARD,
        WALK_TO_GRAVE
    }

    /**
     * handler to the citizen thisis located
     */
    private final EntityCitizen citizen;

    /**
     * Speed at which the citizen will move around
     */
    private final double speed;

    /**
     * Pointer to the closest citizen to look at.
     */
    private Entity closestEntity;

    /**
     * Constant values of mourning
     */
    private static final int MIN_DESTINATION_TO_LOCATION = 225;
    private static final int AVERAGE_MOURN_TIME          = 60 * 5;
    private static final int AVERAGE_STARE_TIME          = 10 * 20;

    /**
     * The position of the graveyard.
     */
    private IBuilding graveyard;

    /**
     * Position of the grave to walk to.
     */
    private BlockPos gravePos;

    /**
     * Instantiates this task.
     *
     * @param citizen the citizen.
     * @param speed   the speed.
     */
    public EntityAIMournCitizen(final EntityCitizen citizen, final double speed)
    {
        super();
        this.citizen = citizen;
        this.speed = speed;

        citizen.getCitizenAI().addTransition(new TickingTransition<>(CitizenAIState.MOURN, () -> {
            reset();
            return true;
        }, () -> MourningState.DECIDE, 20));
        citizen.getCitizenAI().addTransition(new TickingTransition<>(MourningState.DECIDE, () -> true, this::decide, 20));
        citizen.getCitizenAI().addTransition(new TickingTransition<>(MourningState.WALKING_TO_TOWNHALL, () -> true, this::walkToTownHall, 20));
        citizen.getCitizenAI().addTransition(new TickingTransition<>(MourningState.WANDERING, () -> true, this::wander, 20));
        citizen.getCitizenAI().addTransition(new TickingTransition<>(MourningState.STARING, () -> true, this::stare, 20));
        citizen.getCitizenAI().addTransition(new TickingTransition<>(MourningState.WALKING_TO_GRAVEYARD, () -> true, this::walkToGraveyard, 20));
        citizen.getCitizenAI().addTransition(new TickingTransition<>(MourningState.WANDER_AT_GRAVEYARD, () -> true, this::wanderAtGraveyard, 20));
        citizen.getCitizenAI().addTransition(new TickingTransition<>(MourningState.WALK_TO_GRAVE, () -> true, this::walkToGrave, 20));
    }

    /**
     * Path to the townhall.
     *
     * @return IDLE again.
     */
    private IState walkToTownHall()
    {
        final IBuilding building = getMournLocation();
        if (building == null)
        {
            return CitizenAIState.IDLE;
        }

        if (!EntityNavigationUtils.walkToBuilding(citizen, building))
        {
            return MourningState.WALKING_TO_TOWNHALL;
        }

        return CitizenAIState.IDLE;
    }

    /**
     * Path to the graveyard.
     *
     * @return the next state to go to.
     */
    private IState walkToGraveyard()
    {
        if (graveyard == null)
        {
            return MourningState.DECIDE;
        }

        if (!EntityNavigationUtils.walkToBuilding(citizen, graveyard))
        {
            return MourningState.WALKING_TO_GRAVEYARD;
        }

        return MourningState.WANDER_AT_GRAVEYARD;
    }

    /**
     * Wander at the graveyard and visit the graves.
     * While wandering at the graveyard, the chance to stop mourning is doubled.
     *
     * @return the next state to go to.
     */
    private IState wanderAtGraveyard()
    {
        if (graveyard == null)
        {
            return MourningState.DECIDE;
        }

        final GraveyardManagementModule module = graveyard.getModule(GraveyardManagementModule.class);

        if (module == null)
        {
            return MourningState.DECIDE;
        }

        if (!citizen.getNavigation().isDone())
        {
            return MourningState.WANDER_AT_GRAVEYARD;
        }

        // Wander around randomly.
        if (MathUtils.RANDOM.nextInt(100) < 90)
        {
            EntityNavigationUtils.walkToRandomPosWithin(citizen, 10, DEFAULT_SPEED, graveyard.getCorners());
            return MourningState.WANDER_AT_GRAVEYARD;
        }

        // Try find the grave of one of the diseased.
        final Set<Tuple<BlockPos, Direction>> gravePositions = module.getGravePositions();
        for (final Tuple<BlockPos, Direction> gravePos : gravePositions)
        {
            if (WorldUtil.isBlockLoaded(citizen.level, gravePos.getA()))
            {
                final BlockEntity blockEntity = citizen.level.getBlockEntity(gravePos.getA());
                if (blockEntity instanceof TileEntityNamedGrave)
                {
                    final Iterator<String> iterator = citizen.getCitizenData().getCitizenMournHandler().getDeceasedCitizens().iterator();
                    if (!iterator.hasNext())
                    {
                        continue;
                    }
                    final String deathBud = iterator.next();
                    final String firstName = StringUtils.split(deathBud)[0];
                    final String lastName = deathBud.replaceFirst(firstName, "");

                    final List<String> graveNameList = ((TileEntityNamedGrave) blockEntity).getTextLines();
                    if (!graveNameList.isEmpty() && graveNameList.contains(firstName) && graveNameList.contains(lastName))
                    {
                        this.gravePos = gravePos.getA();
                        return MourningState.WALK_TO_GRAVE;
                    }
                }
            }
        }

        return MourningState.DECIDE;
    }

    /**
     * Walk to grave state.
     *
     * @return next state.
     */
    private IState walkToGrave()
    {
        if (gravePos == null)
        {
            return MourningState.DECIDE;
        }

        if (!EntityNavigationUtils.walkToPosInBuilding(citizen, gravePos, graveyard, 3))
        {
            return MourningState.WALK_TO_GRAVE;
        }

        return MourningState.DECIDE;
    }

    /**
     * Wander around randomly.
     *
     * @return also IDLE again.
     */
    private IState wander()
    {
        EntityNavigationUtils.walkToRandomPos(citizen, 10, this.speed);
        return CitizenAIState.IDLE;
    }

    /**
     * State at a random player around.
     *
     * @return Staring if there is a player, else IDLE.
     */
    private IState stare()
    {
        if (this.citizen.getRandom().nextInt(AVERAGE_STARE_TIME) < 1)
        {
            closestEntity = null;
            return CitizenAIState.IDLE;
        }

        if (closestEntity == null)
        {
            closestEntity = this.citizen.level.getNearestEntity(EntityCitizen.class,
              TargetingConditions.DEFAULT,
              citizen,
              citizen.getX(),
              citizen.getY(),
              citizen.getZ(),
              citizen.getBoundingBox().inflate(3.0D, 3.0D, 3.0D));

            if (closestEntity == null)
            {
                return CitizenAIState.IDLE;
            }
        }

        citizen.getLookControl()
          .setLookAt(closestEntity.getX(),
            closestEntity.getY() + (double) closestEntity.getEyeHeight(),
            closestEntity.getZ(),
            (float) citizen.getMaxHeadYRot(),
            (float) citizen.getMaxHeadXRot());
        return MourningState.STARING;
    }

    /**
     * Decide what to do next.
     *
     * @return the next state to go to.
     */
    private IState decide()
    {
        if (!citizen.getNavigation().isDone())
        {
            return CitizenAIState.IDLE;
        }

        if (this.citizen.getRandom().nextBoolean())
        {
            return MourningState.STARING;
        }

        if (this.graveyard == null)
        {
            final IBuilding graveyardBuilding =
              citizen.getCitizenColonyHandler().getColonyOrRegister().getServerBuildingManager().getFirstBuildingMatching(b -> b instanceof BuildingGraveyard && b.getFirstModuleOccurance(
                GraveyardManagementModule.class).hasRestingCitizen(citizen.getCitizenData().getCitizenMournHandler().getDeceasedCitizens()));
            if (graveyardBuilding != null)
            {
                this.graveyard = graveyardBuilding;
            }
        }

        if (graveyard != null)
        {
            return MourningState.WALKING_TO_GRAVEYARD;
        }

        citizen.getLookControl().setLookAt(citizen.getX(), citizen.getY() - 10, citizen.getZ(), (float) citizen.getMaxHeadYRot(),
          (float) citizen.getMaxHeadXRot());

        if (getMournLocation() != null && BlockPosUtil.getDistance2D(this.citizen.blockPosition(), getMournLocation().getPosition()) > MIN_DESTINATION_TO_LOCATION)
        {
            return MourningState.WALKING_TO_TOWNHALL;
        }

        return MourningState.WANDERING;
    }

    public void reset()
    {
        citizen.getCitizenData().setVisibleStatus(null);
        this.graveyard = null;
        this.gravePos = null;
    }

    /**
     * Call this function to get the mourn location
     *
     * @return blockPos of the location to mourn at
     */
    protected IBuilding getMournLocation()
    {
        final IColony colony = citizen.getCitizenColonyHandler().getColonyOrRegister();
        if (colony != null && colony.getServerBuildingManager().hasTownHall())
        {
            return colony.getServerBuildingManager().getTownHall();
        }

        return citizen.getCitizenData().getHomeBuilding();
    }
}

